// prctl(op, arg2, arg3, arg4, arg5)

// Set the name of the calling thread (max 16 bytes)
const char* thread_id = "RPC_Worker";
prctl(PR_SET_NAME, (unsigned long)thread_id, 0, 0, 0);

// Retrieve the current thread name
char name_buffer[16] = {0};
prctl(PR_GET_NAME, (unsigned long)name_buffer, 0, 0, 0);

// Disable core dump generation (security hardening)
prctl(PR_SET_DUMPABLE, 0, 0, 0, 0);

// Check if the process is currently dumpable (returns 0 or 1)
int is_dumpable = prctl(PR_GET_DUMPABLE, 0, 0, 0, 0);

// PR_SET_PDEATHSIG: Send SIGKILL to child upon parent exit
prctl(PR_SET_PDEATHSIG, (unsigned long)SIGKILL, 0, 0, 0);

// Lock process address space to prevent swapping
// prctl(PR_MCLKS_ENFORCE, 0, 0, 0, 0);
// requires PR_SET_MM with PR_SET_MM_FD_WRITE
prctl(PR_SET_MM, PR_SET_MM_FD_WRITE, 0, 0, 0);
